SELECT
    COALESCE(COUNT(FILE_SEQ), 0)
FROM TB_CONTENTFILEINFO
WHERE CON_SEQ = #{conSeq}
  AND DETAIL_SEQ = #{detailSeq}

SELECT
    COALESCE(MAX(FILE_SEQ), 0)
FROM TB_CONTENTFILEINFO
WHERE CON_SEQ = #{conSeq}
  AND DETAIL_SEQ = #{detailSeq}

